from save_review import save
save(1265,{2:'火焰喷射器，又称火焰枪，是多个种族和军队使用的一种基础火焰武器。',7:'火焰喷射器喷出高温燃烧性液体，通常是钷素；这些物质离开武器时便被点燃。它能越过掩体的保护，一次杀伤大量敌人，因而广受重视。由于射程较短，火焰喷射器和更紧凑的火焰手枪都被归为突击武器。帝国和混沌星际战士使用的型号喷射高度挥发性的液态化学混合物，由枪口的引燃火焰点燃。燃料会黏附在目标上，持续自行燃烧；即使没有当场丧命，受害者也会在超高温燃料的灼烧下痛苦死去。',9:'Heresy-era Imperial Flamer 荷鲁斯之乱时期的帝国火焰喷射器',11:'在丛林等地形密集、难以发现敌人的环境中，以及城市战和碉堡突击中，火焰喷射器具有极高的战术价值。它还能焚毁欧克尸体释放的孢子，尤其适合遏止欧克不断滋生的循环。',14:'帝国信条的狂热信徒会用火焰喷射器对付变种人和异端，因为他们相信火焰能够同时洗净肉体与灵魂的罪恶和污秽。',16:'红色救赎者，以及与其相关的涅克罗蒙达考多家族狂信徒等极端帝皇崇拜者，都偏爱这种武器。',18:'修女会极为重视火焰喷射器的净化作用；一名修女获准携带它，是莫大的荣誉。',20:'火蜥蜴战团偏爱近距离交战，因此广泛采用火焰喷射器和热熔武器。',22:'帝国卫队的卡塔昌诸团常被派往茂密丛林，敌人也能像他们一样利用随处可见的掩体。因此，能够剥夺敌人地形优势的火焰喷射器和重型火焰喷射器，尤其受到卡塔昌士兵重视。',24:'机械修会部队使用更先进的智能火焰喷射器。其机魂即使在操作者分心时，也能继续控制武器开火。',38:'钛族的危机战斗服既可使用火焰喷射器，也可装备大型相位等离子火焰喷射器。',40:'Tau Battlesuit wielding twin Flamers 装备两具火焰喷射器的钛族战斗服',42:'Flamespurt 喷焰器',43:'Necrons 太空死灵'},notes={7:'原译将“未被当场杀死，随后继续烧死”误写成另一种立即死亡，现恢复先后关系；cover仍专指掩体。',24:'Cognis与1234智能重型伐木枪统一为智能，不混用认知／智觉。'},terms=[('Flamer','火焰喷射器'),('Cognis Flamer','智能火焰喷射器'),('Baleflamer','灾焰枪'),('Warpflame Weapon','魔焰武器'),('Phased Plasma-Flamer','相位等离子火焰喷射器'),('Flamespurt','喷焰器'),('Gauntlet of Fire','烈焰臂铠'),('Gauntlet of the Conflagrator','纵火者臂铠')],title='火焰喷射器 Flamer')
save(1266,{2:'帝国火焰喷射器又称燃烧器，是帝国各支武装力量使用的火焰喷射武器。',4:'Catachan Jungle Fighter 卡塔昌丛林斗士',8:'Death Korps of Krieg Guardsman 克里格死亡军团士兵',12:'Vostroyan Firstborn 沃斯特洛亚长子团士兵',15:'火焰喷射器射出高度挥发性的液态化学燃料，通常是钷素，接触空气后便引燃，形成大片烈焰。它的射程虽短，对步兵却十分有效。',22:'Mk.IIIa“异端”型——阿斯塔特和帝国卫队常用的型号。',28:'Mk.VII“火蜥蜴”突击火焰喷射器——卡利西斯星区流行的改型，使用混入惰性推进气体的较轻燃料，在更高压力下喷射。枪管的大型扁薄喷嘴使火焰覆盖更宽，但威力较小。',38:'阿诺西斯爆裂火焰喷射器——释放短促的火焰脉冲，主要用于恐吓、逼退目标，而非造成重伤。',40:'Anoxis Burst Flamer 阿诺西斯爆裂火焰喷射器',42:'智能火焰喷射器——机械教部队使用的先进型号，主要装备于护教军和卡塔弗隆机仆。其机魂即使在操作者分心时，也能继续控制武器开火。',44:'Cognis Flamer 智能火焰喷射器',60:'费斯托斯型——大远征和荷鲁斯之乱期间使用的型号。',66:'阿尔泰米亚 Mk.III 净化火焰喷射器——产自制造强大地狱犬喷火坦克的同一铸造世界，使用挥发性钷素，以烈焰焚净异端。',68:'Artemia Mk III Purgation Flamer 阿尔泰米亚 Mk.III 净化火焰喷射器'},notes={15:'本篇称燃料遇空气自燃，1265则称由枪口引燃火焰点燃；按各篇底稿保留机制差异。',42:'此处原文Mechanicum沿机械教，Kataphron指机仆系列，不泛译为所有重型机仆。',66:'Artemia按864阿尔泰米亚主星统一词根，原阿耳忒弥亚留原译对照。'},terms=[('Imperial Flamer','帝国火焰喷射器'),('Heretic Pattern Flamer','异端型火焰喷射器'),('Mark VII Salamander Assault Flamer','Mk.VII 火蜥蜴突击火焰喷射器'),('Absolution Pattern Flamer','赦免型火焰喷射器'),('Anoxis Burst Flamer','阿诺西斯爆裂火焰喷射器'),('Coldfire Pattern','冷焰型'),('Helios-Prime Pattern','赫利俄斯主星型'),('Incinerati Sub-Pattern','焚化子型'),('Phaestos Pattern','费斯托斯型'),('Phaeton Pattern','法厄同型'),('Artemia Mk III Purgation Flamer','阿尔泰米亚 Mk.III 净化火焰喷射器')],title='帝国火焰喷射器 Imperial Flamer')
save(1267,{2:'焚火者火焰投射器是沃坎在大远征期间亲自为火蜥蜴创造的独特复杂武器，由军团的焚火者部队使用，比阿斯塔特军团的标准火焰喷射器更加精巧、强大。它既能像常规型号一样焚烧大片目标，也能收束喷流，形成炽热的切割弧，剖开坚固装甲。',4:'Salamander Pyroclast with the Pyroclast Flame Projector 装备焚火者火焰投射器的火蜥蜴焚火者'},notes={2:'Pyroclasts为火蜥蜴兵种，沿451／454焚火者；原火山岩误取地质词义。'},terms=[('Pyroclast Flame Projector','焚火者火焰投射器')],title='焚火者火焰投射器 Pyroclast Flame Projector')
save(1268,{2:'火焰手枪是帝国火焰喷射器的紧凑手枪型版本，又称燃烧器，可以单手使用。',4:'Hand Flamers 火焰手枪',7:'它的燃料罐较小，射程也明显缩短，适合突击和近战，在近距离焚烧敌人。突击小队常使用这种武器，例如炽天使便会双持火焰手枪。',9:'Hand Flamers 火焰手枪',14:'Word Bearers Akkadic Pattern Hand Flamer 怀言者阿卡迪克型火焰手枪',18:'Coldfire Pattern Hand Flamer 冷焰型火焰手枪',20:'House Escher Hand Flamer 埃舍尔家族火焰手枪',24:'House Orlock Hand Flamer 欧洛克家族火焰手枪',26:'House Goliath Hand Flamer 歌利亚家族火焰手枪',28:'毁灭者型——又称凯迪斯钷素焚烧装置，由卡利西斯星区的审判庭制造。它采用类似等离子枪的技术，产生极高温热能冲击，既比普通火焰手枪温度更高，也更节省燃料。',30:'Inquisition Hand Flamer 审判庭火焰手枪',35:'Blood Angels Hand Flamer 圣血天使火焰手枪',36:'Notable Hand Flamers 著名火焰手枪',39:'德拉基斯——由阿德拉克斯·阿伽顿使用。',41:'伊格纳托斯——由安托·德拉西奥使用。'},notes={2:'统一采用篇名火焰手枪，喷火手枪为原稿同义异译。',28:'burns fat hotter中的fat应为far误写，中文按“温度高得多”理解，不误作燃烧脂肪。'},terms=[('Hand Flamer','火焰手枪'),('Akkadic Pattern','阿卡迪克型'),('Crucible Variant','熔炉型'),('Cadence Promethium Incineration Device','凯迪斯钷素焚烧装置'),('Ignis Pattern','烈焰型'),("Baal's Vengeance",'巴尔的复仇'),('Drakkis','德拉基斯'),('Ignatus','伊格纳托斯'),('Antor Delassio','安托·德拉西奥')])
save(1269,{2:'焚焰枪是星际战士使用的强大火焰喷射器。与传统型号相比，它结构更坚固、枪管更长，能在更远距离释放破坏力更强的火焰。',4:'Infernus Squad marine with Pyreblaster 装备焚焰枪的焚狱者小队战士'},terms=[('Pyreblaster','焚焰枪')])
save(1270,{2:'焚焰炮是肃卫老兵使用的一种星际战士重型火焰喷射器。'},terms=[('Pyrecannon','焚焰炮')])
